//! Golden-master tests for the scanner (FUNCTIONAL_SPEC §3).
//!
//! Expectations below are hand-computed from the committed fixture files:
//! `tests/fixtures/*.log`. A corpus generated by the engine itself is not
//! allowed - these fixtures were written by hand and verified with `cat -ev`.

use logviewer_core::{Format, Scanner, format_from_reader};

const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");

fn fixture(name: &str) -> std::path::PathBuf {
  std::path::Path::new(FIXTURES).join(name)
}

#[test]
fn ksiva_basic() {
  let s = Scanner::open(&fixture("ksiva.log")).unwrap();
  assert_eq!(s.format(), Format::Ksiva);
  assert_eq!(s.line_count(), 3);
  assert_eq!(
    s.raw_line(1),
    &b"2024-01-01T10:00:00.000 app/main LOG_MSG Starting application"[..]
  );
  assert_eq!(
    s.raw_line(3),
    &b"2024-01-01T10:00:02.500 a/b/c wrn Something odd"[..]
  );
}

#[test]
fn plain_basic() {
  let s = Scanner::open(&fixture("plain.log")).unwrap();
  assert_eq!(s.format(), Format::Plain);
  assert_eq!(s.line_count(), 2);
  assert_eq!(
    s.raw_line(1),
    &b"10:00:00.000 0.123 msg cfg Application started"[..]
  );
}

#[test]
fn ksiva_without_trailing_newline() {
  let s = Scanner::open(&fixture("no_trailing_newline.log")).unwrap();
  assert_eq!(s.format(), Format::Ksiva);
  assert_eq!(s.line_count(), 2);
  assert_eq!(s.raw_line(2), &b"2024-01-01T10:00:01.000 app LOG_ERR Bye"[..]);
}

#[test]
fn crlf_lines() {
  let s = Scanner::open(&fixture("crlf.log")).unwrap();
  // Line 1 is "\r\n" (empty), first non-empty line decides the format.
  assert_eq!(s.format(), Format::Ksiva);
  assert_eq!(s.line_count(), 3);
  assert_eq!(s.raw_line(1), &b""[..]);
  assert_eq!(
    s.raw_line(2),
    &b"2024-01-01T10:00:00.000 app LOG_MSG CRLF first"[..]
  );
  assert_eq!(
    s.raw_line(3),
    &b"10:00:01.000 1.000 msg cat CRFL plain"[..]
  );
}

#[test]
fn leading_blanks_and_empty_lines() {
  let s = Scanner::open(&fixture("edge.log")).unwrap();
  assert_eq!(s.format(), Format::Ksiva);
  assert_eq!(s.line_count(), 5);
  assert_eq!(s.raw_line(1), &b""[..]);
  assert_eq!(s.raw_line(2), &b"   "[..]);
  assert_eq!(s.raw_line(5), &b""[..]);
}

#[test]
fn empty_file() {
  let s = Scanner::open(&fixture("empty.log")).unwrap();
  assert_eq!(s.line_count(), 0);
  assert_eq!(s.format(), Format::Ksiva);
}

#[test]
fn reader_helpers() {
  let data = b"alpha\r\nbeta\n\ngamma";
  assert_eq!(format_from_reader(data), Format::Ksiva);
}

/// Dual-path oracle (testable-apps-development rule 3): the optimized memchr-based
/// offset builder must agree with a naive `split`-based reference on every
/// fixture and on adversarial in-memory inputs.
#[test]
fn offsets_agree_with_naive_reference() {
  let cases: Vec<Vec<u8>> = vec![
    Vec::new(),
    b"\n".to_vec(),
    b"single".to_vec(),
    b"trailing\n".to_vec(),
    b"\r\n\r\n".to_vec(),
    b"a\r\nb\nc\n\n\r\nd".to_vec(),
    std::fs::read(fixture("ksiva.log")).unwrap(),
    std::fs::read(fixture("crlf.log")).unwrap(),
    std::fs::read(fixture("edge.log")).unwrap(),
    std::fs::read(fixture("empty.log")).unwrap(),
  ];
  for data in &cases {
    let fast = logviewer_core::build_offsets(data);
    let naive = naive_offsets(data);
    assert_eq!(fast, naive, "offsets diverge on {data:?}");
  }
}

fn naive_offsets(data: &[u8]) -> Vec<u64> {
  if data.is_empty() {
    return Vec::new();
  }
  let mut segments: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
  // Data ending with \n yields a phantom empty final segment.
  if segments.len() > 1 && segments.last().unwrap().is_empty() {
    segments.pop();
  }
  let mut offsets = Vec::with_capacity(segments.len());
  let mut pos: u64 = 0;
  for seg in segments {
    offsets.push(pos);
    pos += seg.len() as u64 + 1; // + the newline that ended the line
  }
  offsets
}
